  func parity( _ c : UInt8) -> Bool {
    let i = c ^ (c >> 1) ^ (c >> 2) ^ (c >> 3) ^
    (c >> 4) ^ (c >> 5) ^ (c >> 6) ^ (c >> 7);
    return (i & 1) == 1
  }

